const applications='pythagorean_applications';
const triples=[[3,4,5],[5,12,13],[8,15,17],[7,24,25]];
function scaledTriple(){
 const scale=ri(1,4);
 return g8Pick(triples).map(value=>value*scale);
}
const integer=value=>String(value).replace('-', '−');
const valueList=values=>values.map(integer).join(', ');
const number=(text,answer,ex,unit='')=>({text,answer:typeof answer==='number'?parseExactNumberInput(answer).rat:answer,ex,unit});
const choice=(text,answer,wrong,ex)=>({text,answer,wrong,ex});
function triangle(base,height,hyp,horizontal,vertical,diagonal,type='triangle',unit='см'){
 return {kind:'g7-qa-geometry74to76',type,a:height,b:base,c:hyp,angle:null,unit,
  labels:{a:horizontal,b:vertical,c:diagonal},aria:type==='isosceles'?'Высота к основанию равнобедренного треугольника':'Схема с прямым углом'};
}
function diagram(task,model){return {...task,model};}
const workouts={
 [applications]:[
  {
   ladder:([a,b,c])=>diagram(number(`Лестница длиной ${c} м опирается на стену. Её нижний конец находится в ${a} м от стены. Найди высоту верхнего конца.`,b,
    `Стена и земля образуют прямой угол. Высота равна √(${c}² − ${a}²) = ${b} м.`,'м'),triangle(a,b,c,`${a} м`,'? м',`${c} м`,'ladder','м')),
   diagonal:([a,b,c])=>diagram(number(`Стороны прямоугольника равны ${a} и ${b} см. Найди диагональ.`,c,
    `Диагональ — гипотенуза. √(${a}² + ${b}²) = ${c} см.`,'см'),triangle(a,b,c,`${a} см`,`${b} см`,'? см','rectangle')),
   cable:([a,b,c])=>diagram(number(`Трос длиной ${c} м идёт от вершины вертикальной мачты высотой ${b} м до колышка на земле. На каком расстоянии от основания мачты находится колышек?`,a,
    `Нужен горизонтальный катет. √(${c}² − ${b}²) = ${a} м.`,'м'),triangle(a,b,c,'? м',`${b} м`,`${c} м`,'triangle','м')),
   walk:([a,b,c])=>number(`Турист прошёл ${a} км на восток, затем ${b} км на север. Найди расстояние по прямой от старта до финиша.`,c,
    `Маршрут образует два перпендикулярных катета. Расстояние равно √(${a}² + ${b}²) = ${c} км.`,'км'),
   verify:([a,b,c])=>{
    const length=ri(0,1)?c:c+1, right=length===c;
    return choice(`Стороны треугольника равны ${a}, ${b} и ${length} см. Есть ли у него прямой угол?`,right?'Да':'Нет',[right?'Нет':'Да'],
     `${a}² + ${b}² = ${c*c}, а ${length}² = ${length*length}. ${right?'Равенство выполняется, поэтому угол напротив самой длинной стороны прямой.':'Равенства нет, поэтому треугольник не прямоугольный.'}`);
   }
  },
  {
   perimeter:([a,b,c])=>number(`Диагональ прямоугольника равна ${c} см, одна сторона — ${a} см. Найди периметр.`,2*(a+b),
    `Вторая сторона равна √(${c}² − ${a}²) = ${b} см. Периметр 2 · (${a} + ${b}) = ${2*(a+b)} см.`,'см'),
   height:([a,b,c])=>diagram(number(`Боковая сторона равнобедренного треугольника равна ${c} см, основание — ${2*a} см. Найди высоту к основанию.`,b,
    `Высота делит основание пополам. Половина равна ${a} см. Высота равна √(${c}² − ${a}²) = ${b} см.`,'см'),
    {...triangle(a,b,c,null,null,null,'isosceles'),labels:{base:`${2*a} см`,side:`${c} см`,height:'? см'}}),
   roof:([a,b,c])=>number(`Поперечное сечение крыши — равнобедренный треугольник шириной ${2*a} м и высотой ${b} м. Сколько метров составляют оба ската в сечении?`,2*c,
    `Высота делит ширину пополам. Каждый скат равен √(${a}² + ${b}²) = ${c} м. Оба ската вместе — ${2*c} м.`,'м'),
   area:([a])=>{
    const base=2*a+1,height=2*a-1,twiceArea=base*height;
    return number(`Гипотенуза прямоугольного треугольника равна √${base*base+height*height} см, один катет — ${base} см. Найди площадь.`,rational(twiceArea,2),
     `Второй катет равен √(${base*base+height*height} − ${base}²) = ${height} см. Площадь равна ${base} · ${height} : 2 = ${rationalRu(rational(twiceArea,2))} см².`,'см²');
   },
   coordinates:([a,b,c])=>{
    const x=ri(-7,-2),y=ri(2,7);
    return number(`Найди расстояние от A(${integer(x)}; ${y}) до B(${integer(x+a)}; ${integer(y-b)}).`,c,
     `Разности координат по модулю равны ${a} и ${b}. По теореме Пифагора получаем √(${a}² + ${b}²) = ${c}.`);
   },
   shortcut:([a,b,c])=>number(`Дорожки вдоль двух соседних сторон прямоугольного парка имеют длины ${a} м и ${b} м. Насколько путь по диагонали короче пути по двум дорожкам?`,a+b-c,
    `Диагональ равна ${c} м. Путь по дорожкам — ${a+b} м. Разница равна ${a+b-c} м.`,'м'),
   slope:([a,b,c])=>number(`Подъём на склон начинается на высоте ${ri(1,8)} м над дорогой. По горизонтали до верхней точки ${a} м, подъём по вертикали от нижней точки равен ${b} м. Сколько метров составит трос от нижней точки до верхней, если добавить ${a} м на крепления?`,c+a,
    `Расстояние между точками равно √(${a}² + ${b}²) = ${c} м. Прибавляем ${a} м на крепления.`,'м')
  },
  {
   twoRamps:([a,b,c])=>number(`Два прямых пандуса соединены горизонтальной площадкой длиной ${b} м. Первый пандус поднимается на ${b} м при горизонтальном ходе ${a} м. Второй поднимается вдвое выше первого, а его горизонтальный ход тоже вдвое больше. Найди длину всего пути.`,3*c+b,
    `Первый пандус имеет длину ${c} м, второй — √((2 · ${a})² + (2 · ${b})²) = ${2*c} м. Прибавляем площадку ${b} м.`,'м'),
   insideBox:([a,b,c])=>{
    const height=ri(2,12);
    return number(`Дно ящика имеет размеры ${a} × ${b} см, высота — ${height} см. Ящик имеет форму прямоугольного параллелепипеда. Найди квадрат длины его пространственной диагонали.`,c*c+height*height,
     `Сначала найдём квадрат диагонали дна: ${a}² + ${b}² = ${c*c}. Затем прибавим квадрат высоты ${height}².`,'см²');
   },
   diagonalArea:([a,b,c])=>number(`Диагональ прямоугольной площадки равна ${c} м. Длина площадки больше ширины на ${b-a} м. Найди площадь.`,a*b,
    `Обозначим ширину x, длину x + ${b-a}. Тогда x² + (x + ${b-a})² = ${c*c}. При x > 0 левая часть возрастает. Подстановка x = ${a} даёт верное равенство, значит площадь ${a} · ${b} = ${a*b} м².`,'м²'),
   rectFromDiagonalAndArea:([a,b,c])=>number(`Диагональ прямоугольника равна ${c} см, площадь — ${a*b} см². Найди его периметр.`,2*(a+b),
    `Обозначим стороны x и y. Тогда x² + y² = ${c*c} и xy = ${a*b}. Поэтому (x + y)² = ${c*c} + 2 · ${a*b} = ${(a+b)**2}. Периметр равен 2 · ${a+b}.`,'см'),
   altitudeArea:([a,b,c])=>number(`Периметр равнобедренного треугольника равен ${2*(a+c)} см, боковая сторона — ${c} см. Найди площадь.`,a*b,
    `Основание равно ${2*(a+c)} − 2 · ${c} = ${2*a} см. Высота делит основание пополам и равна √(${c}² − ${a}²) = ${b} см. Площадь — ${2*a} · ${b} : 2.`,'см²'),
   twoTurns:([a,b,c])=>number(`От старта робот проехал ${3*a} м на восток, ${b} м на север, ${2*a} м на запад и ещё ${b} м на север. Найди квадрат расстояния от старта до финиша.`,a*a+4*b*b,
    `Смещение на восток: ${3*a} − ${2*a} = ${a} м. Смещение на север: ${2*b} м. Сумма квадратов смещений равна ${a*a+4*b*b} м².`,'м²'),
   shortenedLeg:([a,b,c])=>number(`Диагональ прямоугольника равна ${c} см, ширина — ${a} см. На сколько уменьшится квадрат диагонали, если длину уменьшить на ${a} см, а ширину сохранить?`,b*b-(b-a)**2,
    `Исходная длина равна √(${c}² − ${a}²) = ${b} см. Новая длина — ${b-a} см. Квадраты ширины взаимно уничтожаются при вычитании. Разница равна ${b}² − (${b-a})².`,'см²'),
   rhombus:([a,b,c])=>number(`Периметр ромба равен ${4*c} см, одна диагональ — ${2*a} см. Найди площадь ромба.`,2*a*b,
    `Сторона равна ${c} см. Половина второй диагонали равна √(${c}² − ${a}²) = ${b} см. Диагонали равны ${2*a} и ${2*b} см. Их произведение делим пополам.`,'см²'),
   isoscelesTrapezoid:([a,b,c])=>{
    const top=ri(2,13),bottom=top+2*a;
    return number(`Основания равнобедренной трапеции равны ${top} и ${bottom} см, боковая сторона — ${c} см. Найди площадь.`,(top+a)*b,
     `Высоты отсекают на большем основании по ${a} см с каждой стороны. Высота равна √(${c}² − ${a}²) = ${b} см. Умножаем полусумму оснований ${top+a} на высоту.`,'см²');
   },
   distanceComparison:([a,b,c])=>number(`Первая бригада проложила прямой кабель между точками с горизонтальным смещением ${a} м и вертикальным ${b} м. У второй бригады оба смещения на ${a} м больше. На сколько квадрат длины второго кабеля больше квадрата длины первого?`,3*a*a+2*a*b,
    `Первый квадрат равен ${c*c}. Второй равен (${a} + ${a})² + (${b} + ${a})². Вычитаем: получаем ${3*a*a+2*a*b} м².`,'м²')
  }
 ]
};

workouts.heron_formula=[
 {
  semiperimeter:([a,b,c])=>number(`Стороны треугольника равны ${a}, ${b} и ${c} см. Найди полупериметр.`,(a+b+c)/2,
   `Складываем стороны и делим на 2: (${a} + ${b} + ${c}) : 2 = ${(a+b+c)/2} см.`,'см'),
  equalSides:([a,b,c])=>number(`У треугольника стороны ${c}, ${c} и ${2*a} см. Найди разность между полупериметром и одной боковой стороной.`,a,
   `Полупериметр равен ${c+a} см. Вычитаем боковую сторону ${c} см.`,'см'),
  product:([a,b,c])=>{
   const p=(a+b+c)/2;
   return number(`Стороны треугольника равны ${a}, ${b} и ${c} см. Найди произведение p(p − a)(p − b)(p − c) из формулы Герона.`,(a*b/2)**2,
    `Полупериметр равен ${p}. Перемножаем ${p}, ${p-a}, ${p-b} и ${p-c}.`,'см⁴');
  },
  fromProduct:([a,b])=>number(`Для треугольника произведение под корнем в формуле Герона равно ${(a*b)**2} см⁴. Чему равна площадь?`,a*b,
   `Из произведения извлекаем арифметический квадратный корень: √${(a*b)**2} = ${a*b}.`,'см²')
 },
 {
  isosceles:([a,b,c])=>number(`Найди по формуле Герона площадь треугольника со сторонами ${c}, ${c} и ${2*a} см.`,a*b,
   `p = ${c+a}. Под корнем (${c+a}) · ${a} · ${a} · (${c-a}) = ${(a*b)**2}. Площадь равна ${a*b} см².`,'см²'),
  right:([a,b,c])=>{
   const p=(a+b+c)/2;
   return number(`Примени формулу Герона: стороны треугольника равны ${a}, ${b} и ${c} см. Найди площадь.`,a*b/2,
    `p = ${p}. Площадь равна √(${p} · ${p-a} · ${p-b} · ${p-c}) = ${rationalRu(rational(a*b,2))} см².`,'см²');
  },
  fromPerimeter:([a,b,c])=>number(`Периметр равнобедренного треугольника равен ${2*(c+a)} см, боковая сторона — ${c} см. Найди его площадь по формуле Герона.`,a*b,
   `Основание равно ${2*a} см, p = ${c+a}. Подставляем в формулу Герона: √(${c+a} · ${a} · ${a} · ${c-a}) = ${a*b} см².`,'см²'),
  recoverThird:([a,b,c])=>{
   const p=(a+b+c)/2;
   return number(`Полупериметр треугольника равен ${p} см. Две стороны равны ${a} и ${c} см. Найди площадь по формуле Герона.`,a*b/2,
    `Третья сторона равна 2 · ${p} − ${a} − ${c} = ${b} см. Подставляем в формулу: √(${p} · ${p-a} · ${p-b} · ${p-c}) = ${rationalRu(rational(a*b,2))} см².`,'см²');
  }
 },
 {
  general:()=>{
   const k=ri(1,5);
   return number(`Найди площадь треугольника со сторонами ${13*k}, ${14*k} и ${15*k} см.`,84*k*k,
    `Полупериметр равен ${21*k} см. По формуле Герона S = √(${21*k} · ${8*k} · ${7*k} · ${6*k}) = ${84*k*k} см².`,'см²');
  },
  twoTriangles:([a,b,c])=>number(`Первый треугольник имеет стороны ${a}, ${b} и ${c} см. Второй — ${c}, ${c} и ${2*a} см. На сколько квадратных сантиметров площадь второго больше?`,a*b/2,
   `По формуле Герона площади равны ${a*b/2} и ${a*b} см². Вычитаем первую из второй.`,'см²'),
  altitude:([a,b,c])=>number(`Стороны треугольника равны ${a}, ${b} и ${c} см. Используя его площадь по формуле Герона, найди высоту к стороне ${b} см.`,a,
   `Площадь по формуле Герона равна ${rationalRu(rational(a*b,2))} см². Высота равна удвоенной площади, делённой на основание: 2 · ${a*b/2} : ${b} = ${a} см.`,'см'),
  scaled:()=>{
   const k=ri(2,7);
   return number(`У первого треугольника стороны 13, 14 и 15 см. Каждую сторону увеличили в ${k} раз. На сколько квадратных сантиметров выросла площадь?`,84*(k*k-1),
    `По формуле Герона исходная площадь 84 см². Все четыре множителя под корнем возрастают в ${k} раз, поэтому площадь умножается на ${k*k}. Разность равна ${84*(k*k-1)} см².`,'см²');
  }
 }
];
function radicals(minimum=3){
 const r=g8Pick([2,3,5,7]),u=ri(minimum,8),v=ri(1,2);
 const a=u*u+r*v*v,b=2*u*v;
 const term=(n)=>n===1?`√${r}`:`${n}√${r}`;
 return {u,v,r,a,b,term,root:sign=>`√(${a} ${sign} ${term(b)})`,sum:`${u} + ${term(v)}`,
  diff:u>v*Math.sqrt(r)?`${u} − ${term(v)}`:`${term(v)} − ${u}`};
}
workouts.double_radicals=[
 {
  squareSum:()=>{
   const {u,v,term,a}=radicals();
   return number(`Найди рациональную часть квадрата (${u} + ${term(v)})².`,a,`Складываем ${u}² и (${term(v)})²: получаем ${a}.`);
  },
  squareTerm:()=>{
   const {u,v,r,b,term}=radicals();
   return number(`Раскрой квадрат (${u} + ${term(v)})². Какой коэффициент стоит при √${r}?`,b,`Удвоенное произведение даёт 2 · ${u} · ${v} = ${b}.`);
  },
  sign:()=>{
   const {u,v,term,a,b}=radicals();
   return number(`Раскрой квадрат (${u} − ${term(v)})² и запиши результат в виде ${a} + k · ${term(1)}. Найди k.`,-b,
    `Средний член квадрата разности — −2 · ${u} · ${term(v)}. Значит, k = ${integer(-b)}.`);
  },
  magnitude:()=>{
   const {u,v,r,term}=radicals(),positive=u*u>=r*v*v;
   return choice(`Сравни ${u} и ${term(v)}.`,positive?'Первое больше':'Второе больше',[positive?'Второе больше':'Первое больше','Равны'],
    `Оба числа положительные. Их квадраты — ${u*u} и ${r*v*v}.`);
  }
 },
 {
  unpackSum:()=>{
   const m=radicals();
   return choice(`Упрости ${m.root('+')}.`,m.sum,[m.diff,`${m.a} + ${m.term(m.b)}`],
    `Подкоренное выражение равно (${m.sum})². Сумма положительна, поэтому корень равен ${m.sum}.`);
  },
  unpackDifference:()=>{
   const m=radicals();
   return choice(`Упрости ${m.root('−')}.`,m.diff,[m.sum,`−(${m.diff})`],
    `Под корнем квадрат ${m.u} − ${m.term(m.v)}. Корень из квадрата равен модулю выражения, поэтому получаем ${m.diff}.`);
  },
  missingConstant:()=>{
   const m=radicals();
   return number(`Известно, что √(x + ${m.term(m.b)}) = ${m.sum}. Найди x.`,m.a,
    `Возводим правую часть в квадрат. Её рациональная часть равна ${m.u}² + ${m.r*m.v*m.v} = ${m.a}.`);
  },
  compareRadicals:()=>{
   const m=radicals();
   return choice(`Какое выражение больше: ${m.root('+')} или ${m.root('−')}?`,'Первое',['Второе','Оба равны'],
    `Подкоренные выражения неотрицательны. У первого к ${m.a} прибавили ${m.term(m.b)}, у второго вычли.`);
  }
 },
 {
  multiply:()=>{
   const m=radicals(),answer=Math.abs(m.u*m.u-m.r*m.v*m.v);
   return number(`Вычисли ${m.root('+')} · ${m.root('−')}.`,answer,
    `Объединяем корни: под корнем разность квадратов ${m.a}² − ${m.b}² · ${m.r} = ${answer*answer}. Извлекаем корень.`);
  },
  extractFromSum:()=>{
   const m=radicals(6),answer=2*m.u;
   return number(`Вычисли ${m.root('+')} + ${m.root('−')}.`,answer,
    `Тогда ${m.u} > ${m.term(m.v)}. После извлечения корней складываем ${m.u} + ${m.term(m.v)} и ${m.u} − ${m.term(m.v)}. Радикалы сокращаются.`);
  },
  differenceOutsideRoot:()=>{
   const m=radicals(),answer=m.u*m.u>m.r*m.v*m.v?2*m.v:0;
   return number(`Запиши разность ${m.root('+')} − ${m.root('−')} в виде A + B√${m.r}. Найди B.`,answer,
    `Разность равна (${m.sum}) − (${m.diff}). После приведения подобных коэффициент при √${m.r} равен ${answer}.`);
  },
  reciprocal:()=>{
   const m=radicals(),difference=m.u*m.u-m.r*m.v*m.v;
   return number(`Умножь число ${m.root('+')} на ${m.u} − ${m.term(m.v)}. Какой целый результат получится?`,difference,
    `Первый множитель равен ${m.sum}. Произведение сопряжённых выражений равно ${m.u}² − ${m.r*m.v*m.v} = ${integer(difference)}.`);
  }
 }
];

function truthAnswer(question,isTrue,ex){
 return choice(question,isTrue?'Истинно':'Ложно',[isTrue?'Ложно':'Истинно'],ex);
}
workouts.logical_connectives=[
 {
  and:([a,b])=>truthAnswer(`Истинно ли утверждение «${a} < ${b} и ${a+b} — чётное число»?`,(a+b)%2===0,
   'Для союза «и» нужны обе истинные части. Сравнение верно, затем проверяем чётность суммы.'),
  or:([a,b])=>truthAnswer(`Истинно ли утверждение «${a+b} кратно 3 или кратно 5»?`,(a+b)%3===0||(a+b)%5===0,
   'Для «или» достаточно, чтобы выполнялось хотя бы одно из двух условий.'),
  both:()=>{
   const n=12*ri(1,12);
   return truthAnswer(`Истинно ли утверждение «${n} кратно 3 или кратно 4»?`,true,'Обе части истинны, поэтому «или» истинно.');
  },
  choose:([a])=>choice(`Какой союз нужен, чтобы натуральное число было больше ${a} и одновременно чётным?`,'И',['Или','Ни один'],'Слово «одновременно» требует выполнения обоих условий.')
 },
 {
  countAnd:([a,b])=>number(`Сколько натуральных чисел от 1 до ${a+b} одновременно чётны и кратны 3?`,Math.floor((a+b)/6),
   'Оба условия выполняют кратные 6. Делим верхнюю границу на 6 и берём целую часть.'),
  countOr:([a,b])=>{
   const n=a+b,answer=Math.floor(n/2)+Math.floor(n/3)-Math.floor(n/6);
   return number(`Сколько чисел от 1 до ${n} кратны 2 или 3?`,answer,'Складываем числа кратных 2 и 3, затем один раз вычитаем кратные 6.');
  },
  nested:([a,b,c])=>truthAnswer(`Истинно ли «(${a} чётно или ${b} чётно) и ${c} нечётно»?`,(a%2===0||b%2===0)&&c%2===1,
   'Проверяем «или» внутри скобок и соединяем его результат с последней частью через «и».'),
  boundary:([a,b])=>number(`Сколько целых чисел удовлетворяет одновременно x ≥ ${a} и x &lt; ${a+b}?`,b,
   `Подходят числа от ${a} до ${a+b-1} включительно. Их ${b}.`)
 },
 {
  overlap:([a,b])=>{
   const n=a+b,answer=Math.floor(n/2)+Math.floor(n/3)-2*Math.floor(n/6);
   return number(`Сколько чисел от 1 до ${n} делятся ровно на одно из чисел 2 и 3?`,answer,
    'Кратные 6 входят в обе группы. Вычитаем их из каждой группы, затем складываем оставшиеся количества.');
  },
  mixedAndOr:([a,b])=>{
   const n=a+b,hit=Array.from({length:n},(_,i)=>i+1).filter(x=>x%2===0&&(x%3===0||x%5===0));
   return number(`Сколько чисел от 1 до ${n} чётны и делятся хотя бы на одно из чисел 3 и 5?`,hit.length,
    `Нужны кратные 6 или 10. Кратные 30 учитываем один раз. Подходят: ${hit.join(', ')}.`);
  },
  findWitness:([a,b])=>choice(`Найди целое число, при котором истинно (x < ${a} или x > ${a+b}) и x чётно.`,
   2*(a+b),[a,a+b,2*(a+b)+1],'Верный вариант больше верхней границы и чётен. Две границы исключены.'),
  distinguish:([a,b])=>choice(`Для x = ${a} какое условие выполнено?`,
   `x = ${a} или x ≥ ${a+b}`,[`x = ${a} и x ≥ ${a+b}`,`x < ${a} или x ≥ ${a+b}`,`x > ${a} и x ≤ ${a+b}`],
   'В первом условии верна часть x = '+a+'. Условие с «и» требует истинности обеих частей.')
 }
];
workouts.negating_compound_statements=[
 {
  and:([a,b])=>choice(`Выбери отрицание «x > ${a} и x < ${a+b}».`,
   `x ≤ ${a} или x ≥ ${a+b}`,[`x ≤ ${a} и x ≥ ${a+b}`,`x < ${a} или x > ${a+b}`],
   'Отрицаем обе части и заменяем «и» на «или». Обе границы входят в отрицание.'),
  or:([a,b])=>choice(`Выбери отрицание «x < ${a} или x > ${a+b}».`,
   `x ≥ ${a} и x ≤ ${a+b}`,[`x ≥ ${a} или x ≤ ${a+b}`,`x > ${a} и x < ${a+b}`],
   'Отрицаем обе части и заменяем «или» на «и».'),
  direct:([a])=>truthAnswer(`При x = ${a} истинно ли отрицание «x > ${a}»?`,true,'При равенстве строгое неравенство ложно. Его отрицание истинно.'),
  parity:()=>{
   const n=ri(3,15);
   return choice(`Как сказать «неверно, что число чётное и делится на ${n}»?`,`Число нечётное или не делится на ${n}`,
    [`Число нечётное и не делится на ${n}`,`Число чётное или делится на ${n}`],'Для отрицания «и» достаточно, чтобы нарушилось хотя бы одно условие.');
  }
 },
 {
  inclusive:([a,b])=>choice(`Отрицай «x ≥ ${a} и x < ${a+b}».`,`x < ${a} или x ≥ ${a+b}`,
   [`x ≤ ${a} или x > ${a+b}`,`x < ${a} и x ≥ ${a+b}`],'При отрицании x ≥ a переходит в x < a, а x < b — в x ≥ b.'),
  count:([a,b])=>number(`Для скольких целых x от 0 до ${a+b} включительно ложно условие x ≥ ${a} и x ≤ ${a+b}?`,a,
   `В данном наборе ложность означает x < ${a}. Это числа от 0 до ${a-1}.`),
  except:([a])=>choice(`Как записать отрицание «x = ${a} или x = ${-a}»?`,`x ≠ ${a} и x ≠ ${-a}`,
   [`x ≠ ${a} или x ≠ ${-a}`,`x = ${a} и x = ${-a}`],'При отрицании «или» ни одна часть исходного утверждения не должна выполняться.'),
  exists:([a,b])=>choice(`Отрицай «все числа от ${a} до ${a+b} чётные».`,'Хотя бы одно из этих чисел нечётное',
   ['Все эти числа нечётные','Хотя бы одно из этих чисел чётное'],'Для опровержения утверждения о всех числах достаточно одного контрпримера.')
 },
 {
  nested:([a,b])=>choice(`Для целого x что равносильно отрицанию «x ≤ ${a} и (x < ${b} или x чётное)»?`,
   `x > ${a} или (x ≥ ${b} и x нечётное)`,[`x > ${a} и (x ≥ ${b} или x нечётное)`,`x ≥ ${a} или (x > ${b} и x нечётное)`],
   'Снаружи «и» становится «или», внутри «или» становится «и». Каждое простое условие заменяем его отрицанием.'),
  countNested:([a,b])=>{
   const n=a+b,answer=Array.from({length:n},(_,i)=>i+1).filter(x=>x>=a&&x%2!==0).length;
   return number(`Сколько чисел от 1 до ${n} делают ложным условие «x < ${a} или x чётное»?`,answer,
    `Отрицание требует x ≥ ${a} и нечётности. Считаем нечётные числа на отрезке от ${a} до ${n}.`);
  },
  neither:([a,b])=>{
   const n=a+b,answer=n-Math.floor(n/2)-Math.floor(n/3)+Math.floor(n/6);
   return number(`Сколько чисел от 1 до ${n} не делятся ни на 2, ни на 3?`,answer,
    'Вычитаем из общего количества кратные 2 и 3. Чтобы кратные 6 не вычесть дважды, прибавляем их количество один раз.');
  },
  gaps:([a,b])=>number(`Для скольких целых x от 0 до ${a+2*b} неверно «x < ${a} или (x ≥ ${a+b} и x < ${a+2*b})»?`,b+1,
   `Остаются целые от ${a} до ${a+b-1} и правая граница ${a+2*b}. Всего ${b+1}.`)
 }
];

const signed = value => value < 0 ? ' − ' + Math.abs(value) : ' + ' + value;
const linear = (coefficient, constant, variable='x') => (coefficient===1?'':coefficient===-1?'−':integer(coefficient))+variable+(constant?signed(constant):'');
const shift = k => 'x'+signed(-k);
const fraction = (a,b) => rationalHtml(rational(a,b),false);
const worked = (rule,example) => '<p>'+rule+'</p><p><b>Пример.</b> '+example+'</p>';

function decomposition(m,n,a,b) {
 const first=shift(a),second=shift(b);
 return {first,second,expression:frac(linear(m+n,-m*b-n*a),`(${first})(${second})`),m,n,a,b};
}
function decompositionTask(m,n,a,b,target) {
 const {first,second,expression}=decomposition(m,n,a,b);
 const value=target==='A'?m:n,at=target==='A'?a:b;
 return number(`При допустимых x выполни разложение: ${expression} = ${frac('A',first)} + ${frac('B',second)}. Найди ${target}.`,value,
  `Умножаем на (${first})(${second}). Получаем равенство числителей. В это равенство подставляем x = ${integer(at)}: одно слагаемое исчезает, из другого получаем ${target} = ${integer(value)}.`);
}
workouts.partial_fraction_decomposition=[
 {
  common:([a,b])=>number(`Сложи ${frac(a,'x')} и ${frac(b,'x')}. Чему равен числитель дроби со знаменателем x?`,a+b,`Складываем числители: ${a} + ${b} = ${a+b}.`),
  split:([a,b])=>number(`Заполни пропуск: ${frac(linear(a,b),'x')} = ${a} + ${frac('A','x')}, x ≠ 0. Найди A.`,b,`Разбиваем числитель на ${a}x и ${b}. Первое слагаемое при делении на x даёт ${a}.`),
  denominator:([a,b])=>choice(`После приведения ${frac(a,shift(a))} + ${frac(b,shift(b))} к общему знаменателю какой множитель домножает первый числитель?`,shift(b),[shift(a),'1',String(a)],`Первой дроби не хватает множителя ${shift(b)}.`),
  linear:([a,b])=>number(`Выдели целую часть: ${frac(linear(a,b-a*a),shift(a))} = A + ${frac(b,shift(a))}. Найди A.`,a,`После умножения на ${shift(a)} коэффициент при x справа равен A, слева — ${a}.`)
 },
 {
  first:([a,b])=>decompositionTask(a,2,1,2+b,'A'),
  second:([a,b])=>decompositionTask(3,a,-b,2,'B'),
  gap:([a,b])=>number(`Найди A: ${frac(b-a,`(${shift(a)})(${shift(b)})`)} = ${frac('A',shift(b))} − ${frac('A',shift(a))}.`,1,`Справа после приведения к общему знаменателю получается A · (${b} − ${a}).`),
  quadratic:([a,b])=>number(`Разложи ${frac(linear(a,b),`x(x+${b})`)} = ${frac('A','x')} + ${frac('B',`x+${b}`)}. Найди B.`,a-1,`После умножения на x(x+${b}) подстановка 0 даёт A = 1. Коэффициент при x равен A + B = ${a}.`)
 },
 {
  negative:([a,b])=>decompositionTask(-a,b,-2,3,'A'),
  both:([a,b])=>{
   const {first,second,expression}=decomposition(a,b,1,3);
   return number(`Дано разложение ${expression} = ${frac('A',first)} + ${frac('B',second)} при допустимых x. Найди A · B.`,a*b,`В равенстве числителей подставляем 1 и 3. Получаем A = ${a} и B = ${b}. Перемножаем.`);
  },
  polynomial:([a,b])=>number(`Выдели многочлен: ${frac(`x²+${a}x+${b}`,shift(a))} = x + C + ${frac('D',shift(a))}. Найди D.`,b+2*a*a,
   `Домножаем на ${shift(a)}. В равенстве числителей подставляем x = ${a}. Справа остаётся D, слева — ${a*a} + ${a*a} + ${b}.`),
  repeated:([a,b])=>number(`В разложении ${frac(linear(a,b),`(${shift(a)})²`)} = ${frac('A',shift(a))} + ${frac('B',`(${shift(a)})²`)} найди B.`,a*a+b,
   `Домножаем на (${shift(a)})². При x = ${a} в полученном равенстве справа остаётся B, слева — ${a*a} + ${b}.`)
 }
];

function solutionCount(condition,count,ex) {
 return choice(condition+' Сколько решений?',String(count),['0','1','2','Бесконечно много'].filter(value=>value!==String(count)),ex);
}
workouts.parameter_equations=[
 {
  substitute:([a,b])=>number(`Реши ax = ${a*b} при a = ${a}.`,b,`Делим обе части на ${a}.`),
  zero:([a,b])=>solutionCount(`В уравнении ax = ${b} положили a = 0.`,0,`Левая часть равна 0, а справа стоит ${b}.`),
  identity:([a,b])=>solutionCount(`В уравнении (a − ${a})x = 0 положили a = ${a}.`,'Бесконечно много','Получается 0 = 0 при любом x.'),
  target:([a,b])=>number(`При каком a число x = ${a} является корнем уравнения x + a = ${a+b}?`,b,`Подставляем x = ${a} и вычитаем ${a}.`)
 },
 {
  none:([a,b])=>number(`При каком a уравнение (a − ${a})x = ${b} не имеет решений?`,a,`Справа ненулевое число, поэтому нужно, чтобы коэффициент при x стал нулём.`),
  one:([a,b])=>number(`При каком a уравнение x² = a − ${a+b} имеет ровно один действительный корень?`,a+b,`Один корень получается при нулевой правой части: x² = 0.`),
  only:([a,b])=>solutionCount(`В уравнении x² − ${a+b}x + a = 0 положили a = ${a*b}.`,2,`Левая часть равна (x − ${a})(x − ${b}). Поэтому корни ${a} и ${b} различны.`),
  identical:([a,b])=>number(`При каком a решениями уравнения ax − ${b} = ${a}x − ${b} являются все действительные числа?`,a,`Свободные члены уже равны. Коэффициенты при x должны совпасть.`)
 },
 {
  repeatedRoot:([a,b])=>number(`При каком k уравнение x² − ${2*a}x + k = 0 имеет ровно один корень?`,a*a,
   `Дискриминант равен ${4*a*a} − 4k. При единственном корне он равен нулю.`),
  excluded:([,b])=>number(`При каком k уравнение ${frac('x − k',shift(b))} = 0 не имеет корней?`,b,
   `Нуль числителя даёт x = k. Единственный кандидат запрещён ровно при k = ${b}.`),
  twoCandidates:([a,b])=>number(`При каком k уравнение ${frac(`(x − ${a})(x − ${b})`,'x − k')} = 0 имеет единственный корень x = ${b}?`,a,
   `Нули числителя — ${a} и ${b}. Чтобы оставить только ${b}, знаменатель должен исключить x = ${a}.`),
  doubleCondition:([a,b])=>number(`При каких k уравнение x² = (k − ${a})(k − ${b}) имеет ровно один корень? Запиши сумму всех таких k.`,a+b,
   `Один корень получается, когда произведение равно нулю. Параметр равен ${a} или ${b}. Их сумма — ${a+b}.`)
 }
];

workouts.inequality_proofs=[
 {
  square:([a])=>choice(`Какой факт доказывает, что (x − ${a})² ≥ 0 при любом действительном x?`,'Квадрат числа неотрицателен',['x всегда положителен','x всегда больше '+a], 'Если число положительно или отрицательно, его квадрат положителен. Квадрат нуля равен нулю.'),
  equality:([a])=>number(`При каком x в неравенстве (x − ${a})² ≥ 0 достигается равенство?`,a,`Квадрат равен нулю, только если x − ${a} = 0.`),
  difference:([a,b])=>number(`Докажи ${a+b}x ≥ ${a}x для x ≥ 0. Какой коэффициент стоит перед x в разности левой и правой частей?`,b,`Разность равна (${a+b} − ${a})x = ${b}x. Оба множителя неотрицательны.`),
  add:([a,b])=>choice(`Если x ≥ ${a} и y ≥ ${b}, какое неравенство сразу следует из сложения?`,`x + y ≥ ${a+b}`,[`x + y ≤ ${a+b}`,`x + y > ${a+b}`], 'При сложении двух нестрогих неравенств одинакового направления знак сохраняется. При обоих равенствах сумма равна нижней границе.')
 },
 {
  complete:([a])=>number(`Докажи x² − ${2*a}x + k ≥ 0 при любых x с помощью полного квадрата. Найди наименьшее k.`,a*a,`Левая часть равна (x − ${a})² + k − ${a*a}. Минимум достигается при x = ${a}.`),
  twoSquares:([a,b])=>number(`Найди минимально возможное значение x² − ${2*a}x + ${a*a+b}. Это число и есть точная нижняя граница.`,b,`Выделяем квадрат: (x − ${a})² + ${b}. При x = ${a} квадрат равен нулю.`),
  amgm:([a,b])=>number(`Для положительных x и y верно x² + y² ≥ 2xy. При xy = ${a*b} найди точную нижнюю границу x² + y².`,2*a*b,`Разность равна (x − y)². Равенство достигается при x = y = √${a*b}.`),
  counter:([a,b])=>choice(`Какой x опровергает утверждение x² ≥ ${a*a} для всех действительных x?`,String(a-1),[String(a),String(b),String(-b)],`Число ${a-1} по модулю меньше ${a}, поэтому его квадрат меньше ${a*a}.`)
 },
 {
  multiplier:([a,b])=>number(`При каком наименьшем k выполняется x² + k ≥ ${2*a}x + ${b} для всех действительных x?`,a*a+b,`Разность частей равна (x − ${a})² + k − ${a*a+b}. Для всех x она неотрицательна ровно при k ≥ ${a*a+b}.`),
  fractionBound:([a,b])=>number(`Для x > 0 докажи x + ${frac(a*a*b*b,'x')} ≥ C. Какое наибольшее C можно взять?`,2*a*b,`Умножаем разность с C = ${2*a*b} на положительный x. Получается (x − ${a*b})² ≥ 0. При x = ${a*b} есть равенство.`),
  interval:([a,b])=>number(`Известно, что ${a} ≤ x ≤ ${b}. Найди сумму всех значений x, при которых (x − ${a})(x − ${b}) ≤ 0 обращается в равенство.`,a+b,`В данном промежутке множители имеют разные знаки или один из них равен нулю. Равенство достигается только на концах.`),
  squares:([a,b])=>number(`Какова точная нижняя граница (x − ${a})² + (x + ${a})² + ${b} при действительных x?`,2*a*a+b,`После раскрытия скобок линейные члены уничтожаются. Получаем 2x² + ${2*a*a+b}, и равенство достигается при x = 0.`)
 }
];

function fractionalPart(a,b) { return rational(a-Math.floor(a/b)*b,b); }
function rationalTask(a,b,findPart) {
 const result=findPart?fractionalPart(a,b):Math.floor(a/b);
 const lower=Math.floor(a/b);
 return number(`Найди ${findPart?'дробную':'целую'} часть числа ${fraction(a,b)}.`,result,
  `Число не меньше ${integer(lower)} и меньше ${integer(lower+1)}. Целая часть — ${integer(lower)}. Дробная часть равна разности числа и его целой части.`);
}
workouts.integer_fractional_parts=[
 {
  positiveFloor:([a,b])=>rationalTask(a+b,a,false),
  positivePart:([a,b])=>rationalTask(a+b,a,true),
  integer:([a])=>number(`Найди дробную часть числа ${integer(-a)}.`,0,'Разность числа и его целой части равна нулю для любого целого числа.'),
  interval:([a])=>choice(`Где находится x, если его целая часть равна ${a}?`,`[${a}; ${a+1})`,[`(${a}; ${a+1}]`,`[${a}; ${a+1}]`],`Число может равняться ${a}, но ${a+1} уже имеет другую целую часть.`)
 },
 {
  negativeFloor:([a,b])=>rationalTask(-a-b-1,a,false),
  negativePart:([a,b])=>rationalTask(-a-b-1,a,true),
  recover:([a,b])=>number(`Целая часть числа равна ${integer(-b)}, дробная часть — ${fraction(1,a)}. Найди число.`,rational(1-b*a,a),`Складываем целую и дробную части: ${integer(-b)} + ${fraction(1,a)}.`),
  sum:([a,b])=>number(`Найди сумму целых частей чисел ${fraction(a+1,a)} и ${fraction(-b-1,b)}.`,-1,'Первое число между 1 и 2, второе между −2 и −1. Целые части равны 1 и −2.')
 },
 {
  opposite:([a,b])=>number(`Найди сумму дробных частей чисел ${fraction(b*a+1,a)} и ${fraction(-b*a-1,a)}.`,1,`Дробные части — ${fraction(1,a)} и ${fraction(a-1,a)}. Они дополняют друг друга до 1.`),
  equation:([a,b])=>number(`Целая часть x равна ${integer(-a)}, а дробная часть числа 2x равна ${fraction(1,b)}. Найди сумму всех подходящих x.`,rational(-4*a*b+b+2,2*b),
   `Дробная часть x лежит от 0 до 1. После удвоения подходят ${fraction(1,2*b)} и ${fraction(b+1,2*b)}. К каждой прибавляем ${integer(-a)}, затем складываем числа.`),
  boundaries:([a,b])=>number(`Сколько чисел вида k/2 при целом k имеют целую часть не меньше ${integer(-a)} и не больше ${b}?`,2*(a+b+1),
   `Подходят числа из [${integer(-a)}; ${b+1}). На каждый целый промежуток приходятся целое число и число с дробной частью 1/2.`),
  unsplit:([a,b])=>number(`На сколько целая часть суммы ${fraction(a-1,a)} и ${fraction(b-1,b)} больше суммы их целых частей?`,1,
   `Обе дроби меньше 1, каждая больше 1/2. Их сумма больше 1 и меньше 2. Целые части слагаемых равны 0.`)
 }
];

workouts.reciprocal_power_functions=[
 {
  minusOne:([a])=>number(`Найди значение y = x⁻¹ при x = ${integer(-a)}.`,rational(-1,a),`x⁻¹ = 1/x. Подставляем x = ${integer(-a)}.`),
  minusTwo:([a])=>number(`Найди значение y = x⁻² при x = ${a}.`,rational(1,a*a),`x⁻² = 1/x². Квадрат ${a} равен ${a*a}.`),
  scope:()=>choice('Какое значение x исключено из области определения y = x⁻²?','0',['−1','1','Все отрицательные числа'],'В знаменателе x². Он обращается в нуль только при x = 0.'),
  signs:([a])=>choice(`Какого знака значение y = x⁻¹ при x = ${integer(-a)}?`,'Отрицательного',['Положительного','Равно нулю'],'Числитель положителен, знаменатель отрицателен.')
 },
 {
  nodes:([a])=>number(`Сколько общих точек у графика y = x⁻² и прямой y = ${fraction(1,a*a)}?`,2,`Равенство эквивалентно x² = ${a*a}. Подходят ${a} и ${integer(-a)}.`),
  compare:([a,b])=>choice(`Для какого x значение y = x⁻² больше?`,`x = ${a}`,[`x = ${b}`,'Значения равны'],`Поскольку ${a} < ${b}, обратное к ${a*a} больше обратного к ${b*b}.`),
  parity:()=>choice('Как расположены ветви графика y = x⁻²?','Симметрично относительно оси Oy',['Симметрично относительно начала координат','Обе в правой полуплоскости'],'Квадраты противоположных аргументов равны.'),
  invert:([a])=>number(`При каком x выполнено x⁻¹ = ${fraction(-1,a)}?`,-a,`Обращаем обе ненулевые части: x = ${integer(-a)}.`)
 },
 {
  intersection:()=>number('Найди абсциссу общей точки графиков y = x⁻¹ и y = x⁻².',1,'При x ≠ 0 домножаем равенство 1/x = 1/x² на x². Получаем x = 1.'),
  inequality:([a])=>number(`Сколько целых x удовлетворяют x⁻² > ${fraction(1,a*a)}?`,2*(a-1),`При x ≠ 0 условие равносильно x² < ${a*a}. Подходят ненулевые целые с |x| < ${a}.`),
  scaled:([a])=>number(`При каких действительных x верно ${a*a}x⁻² = 1? Запиши произведение всех таких x.`,-a*a,`x² = ${a*a}. Корни противоположны: ${a} и ${integer(-a)}.`),
  difference:([a])=>number(`При каком отличном от нуля x разность ${a}x⁻² − x⁻¹ равна нулю?`,a,`Домножаем равенство на x². Получаем ${a} − x = 0.`)
 }
];

const angleSum = sides => 180*(sides-2);
const polygon = () => ri(5,12);

workouts.convex_polygons=[
 {
  definition:([a])=>choice(`Как называется ${a+3}-угольник, у которого все диагонали лежат внутри фигуры?`,'Выпуклый',['Вогнутый','Самопересекающийся'],'У выпуклого многоугольника все диагонали проходят внутри него.'),
  triangles:()=>{const sides=polygon();return number(`На сколько треугольников делят выпуклый ${sides}-угольник диагонали из одной вершины?`,sides-2,`Получается n − 2 = ${sides-2} треугольников.`);},
  total:()=>{const sides=polygon();return number(`Найди сумму внутренних углов выпуклого ${sides}-угольника.`,angleSum(sides),`У каждой из ${sides-2} частей-треугольников сумма углов составляет 180°.`,'°');},
  count:()=>{const sides=polygon();return number(`Сколько диагоналей выходит из одной вершины выпуклого ${sides}-угольника?`,sides-3,'Из числа вершин исключаем исходную и две соседние.');}
 },
 {
  reverse:()=>{const sides=polygon();return number(`Сумма углов выпуклого многоугольника равна ${angleSum(sides)}°. Сколько у него сторон?`,sides,`Делим ${angleSum(sides)}° на 180° и прибавляем 2.`);},
  diagonalTotal:()=>{const sides=polygon();return number(`Сколько диагоналей в выпуклом ${sides}-угольнике?`,sides*(sides-3)/2,`Из каждой вершины идут ${sides-3} диагонали. Делим произведение на 2, так как у диагонали два конца.`);},
  regular:()=>{const sides=g8Pick([5,6,8,9,10,12]);return number(`Найди величину внутреннего угла правильного ${sides}-угольника.`,angleSum(sides)/sides,`Все углы равны. Делим ${angleSum(sides)}° на ${sides}.`,'°');},
  missing:()=>{const sides=g8Pick([5,6,8,9,10,12]),regular=angleSum(sides)/sides,delta=ri(1,10);return number(`В выпуклом ${sides}-угольнике один угол на ${delta}° больше ${regular}°, остальные, кроме ещё одного, равны ${regular}°. Найди оставшийся угол.`,regular-delta,`Сумма равна ${angleSum(sides)}°. При неизменной сумме прибавка ${delta}° к одному углу компенсируется вычитанием из другого.`,'°');}
 },
 {
  inverseDiagonals:()=>{const sides=polygon();return number(`В выпуклом многоугольнике ${sides*(sides-3)/2} диагоналей. Найди число вершин.`,sides,`Ищем n ≥ 3, для которого n(n − 3) = ${sides*(sides-3)}. Левая часть строго растёт на целых n ≥ 3. Подходит ${sides}.`);},
  exterior:()=>{const sides=g8Pick([5,6,8,9,10,12]);return number(`Внутренний угол правильного многоугольника равен ${180-360/sides}°. Сколько диагоналей выходит из его вершины?`,sides-3,`Внешний угол равен ${360/sides}°. Внешние углы в сумме дают 360°, значит вершин ${sides}, из одной вершины выходят ${sides-3} диагонали.`);},
  cut:()=>{const sides=ri(7,12),part=ri(3,5);return number(`Диагональ делит выпуклый ${sides}-угольник на ${part}-угольник и ещё один многоугольник. Найди сумму углов второго.`,angleSum(sides+2-part),`Концы диагонали входят в обе части. Во второй части ${sides} + 2 − ${part} = ${sides+2-part} вершин.`,'°');},
  change:()=>{const sides=polygon(),extra=ri(1,4);return number(`В выпуклом ${sides}-угольнике число сторон увеличили на ${extra}. На сколько выросло число диагоналей?`,((sides+extra)*(sides+extra-3)-sides*(sides-3))/2,`Вычитаем значения n(n − 3) : 2 для ${sides+extra} и ${sides} вершин.`);}
 }
];

workouts.pythagorean_converse=[
 {
  matches:([a,b,c])=>choice(`Образуют ли ${a}, ${b} и ${c} см стороны прямоугольного треугольника?`,'Да',['Нет'],`${a}² + ${b}² = ${c*c} = ${c}².`),
  misses:([a,b,c])=>choice(`Стороны треугольника равны ${a}, ${c+1} и ${b} см. Есть ли прямой угол?`,'Нет',['Да'],`Длиннейшая сторона — ${c+1} см. Её квадрат не равен ${a}² + ${b}² = ${c*c}.`),
  longest:([a,b,c])=>choice(`Какую длину нужно взять за предполагаемую гипотенузу при проверке треугольника со сторонами ${b}, ${c} и ${a} см?`,String(c),[String(a),String(b)],'Гипотенуза лежит напротив прямого угла и длиннее обоих катетов.'),
  rule:([a,b])=>choice(`Сторона c у треугольника длиннее сторон a и b. Какое равенство позволяет доказать, что есть прямой угол?`,'c² = a² + b²',['a² = b² + c²','c = a + b','c² = (a + b)²'],'Сравниваем квадрат самой длинной стороны с суммой квадратов двух остальных.')
 },
 {
  vertex:([a,b,c])=>choice(`В треугольнике ABC: AB = ${b}, BC = ${a}, AC = ${c} см. Какой угол прямой?`,'B',['A','C','Прямого угла нет'],`AC² = AB² + BC². Прямой угол находится напротив AC.`),
  squares:([a,b,c])=>choice(`Квадраты трёх сторон треугольника равны ${b*b}, ${a*a} и ${c*c}. Есть ли прямой угол?`,'Да',['Нет'],`${a*a} + ${b*b} = ${c*c}. Равенство выполняется для длиннейшей стороны.`),
  correction:([a,b,c])=>number(`В измерениях получили длины ${a}, ${b} и ${c+2} см. На сколько надо уменьшить последнюю длину, чтобы треугольник стал прямоугольным с этой гипотенузой?`,2,`Гипотенуза при данных катетах должна быть √(${a}² + ${b}²) = ${c} см.`,'см'),
  choose:([a,b,c])=>choice(`Какая тройка может быть сторонами прямоугольного треугольника?`,valueList([a,b,c]),[valueList([a,b,c+1]),valueList([a,b,c-1]),valueList([a,b+1,c])],`В верной тройке ${a}² + ${b}² = ${c}². В каждой из остальных изменена ровно одна сторона.`)
 },
 {
  rectangle:([a,b,c])=>choice(`Четырёхугольник ABCD — параллелограмм. AB = ${a} см, BC = ${b} см, AC = ${c} см. Какой вывод верен?`,'Это прямоугольник',['Это ромб','Это квадрат','Угол B острый'],`AC² = AB² + BC², следовательно ∠B = 90°. Параллелограмм с прямым углом — прямоугольник.`),
  coordinates:([a,b])=>choice(`У треугольника координаты A(0; 0), B(${a}; ${b}), C(${a}; 0). При какой вершине прямой угол?`,'C',['A','B','Прямого угла нет'],`AB² = ${a*a+b*b}, AC² = ${a*a}, BC² = ${b*b}. Равенство выполняется для стороны AB, противолежащей C.`),
  angleArea:([a,b,c])=>number(`Стороны треугольника равны ${a}, ${b} и ${c} см. Проверь, что угол между двумя меньшими сторонами прямой, и найди площадь треугольника.`,rational(a*b,2),`${a}² + ${b}² = ${c}². Поэтому меньшие стороны — катеты. Площадь равна половине их произведения.`,'см²'),
  ratio:([a,b,c])=>number(`Стороны треугольника относятся как ${a} : ${b} : ${c}, периметр равен ${2*(a+b+c)} см. Найди высоту к стороне, которая окажется гипотенузой.`,rational(2*a*b,c),`Длины равны ${2*a}, ${2*b} и ${2*c}. По обратной теореме меньшие стороны — катеты. Удвоенная площадь ${4*a*b}, делим её на гипотенузу ${2*c}.`,'см')
 }
];

const bisectors='Биссектрисы',medians='Медианы',heights='Высоты',perpendiculars='Серединные перпендикуляры';
const centers=[bisectors,medians,heights,perpendiculars];
const pointName=['центр вписанной окружности','центроид','ортоцентр','центр описанной окружности'];
function whichCenter(text,index,ex) {return choice(text,centers[index],centers.filter((_,i)=>i!==index),ex);}
workouts.triangle_centers=[
 {
  inside:()=>whichCenter('Какие линии треугольника пересекаются в центре его вписанной окружности?',0,'Эта точка равноудалена от трёх сторон.'),
  mass:()=>whichCenter('Какие линии треугольника пересекаются в центре тяжести?',1,'Центроид делит каждую медиану в отношении 2 : 1, считая от вершины.'),
  orthocenter:()=>whichCenter('Какие линии треугольника или их продолжения пересекаются в ортоцентре?',2,'В тупоугольном треугольнике пересекаются прямые, содержащие высоты.'),
  outside:()=>whichCenter('Какие линии пересекаются в центре окружности, проходящей через все вершины треугольника?',3,'Точка равноудалена от вершин благодаря свойству серединного перпендикуляра.'),
  radius:([a])=>number(`Вписанная окружность треугольника имеет радиус ${a} см. На каком расстоянии от каждой стороны лежит точка пересечения биссектрис?`,a,'Точка пересечения биссектрис — центр вписанной окружности. Расстояние до каждой стороны равно радиусу.','см')
 },
 {
  position:()=>choice('Где находится ортоцентр тупоугольного треугольника?','Вне треугольника',['Внутри треугольника','В середине наибольшей стороны'],'К двум сторонам высоты выходят за пределы фигуры.'),
  distance:([a,b])=>number(`Точка I лежит на биссектрисах треугольника и удалена от AB на ${a} см. Каково расстояние от I до BC?`,a,'Центр вписанной окружности равноудалён от всех сторон.','см'),
  right:([a,b,c])=>number(`У прямоугольного треугольника гипотенуза равна ${2*c} см. Найди расстояние от центра описанной окружности до вершины прямого угла.`,c,'Центр описанной окружности — середина гипотенузы, радиус равен её половине.','см'),
  name:()=>{const index=ri(0,3);return choice(`Как называется точка, в которой пересекаются линии группы «${centers[index].toLowerCase()}» треугольника?`,pointName[index],pointName.filter((_,i)=>i!==index),'Каждая из четырёх точек определяется пересечением своего семейства линий.');}
 },
 {
  rightDifference:([a,b,c])=>number(`У прямоугольного треугольника гипотенуза ${2*c} см. Найди расстояние между ортоцентром и центром описанной окружности.`,c,
   'Ортоцентр — вершина прямого угла, второй центр — середина гипотенузы. Расстояние равно радиусу описанной окружности.','см'),
  isosceles:([a,b])=>number(`В равнобедренном треугольнике высота из вершины к основанию равна ${3*b} см. Найди расстояние от центроида до основания.`,b,
   'В этом треугольнике высота к основанию совпадает с медианой. Центроид делит её в отношении 2 : 1 от вершины.','см'),
  perpendicular:([a,b,c])=>number(`Середина AB обозначена M. Серединные перпендикуляры к сторонам треугольника пересекаются в O. Даны AM = ${a} см, OM = ${b} см. Найди радиус описанной окружности.`,c,
   `OM перпендикулярна AM. Радиус OA = √(${a}² + ${b}²) = ${c} см.`,'см'),
  equilateral:([a,b])=>number(`Высота равностороннего треугольника равна ${3*b} см. На сколько радиус описанной окружности больше радиуса вписанной?`,b,
   `Все четыре центра совпадают. Высота делится в отношении 2 : 1, поэтому радиусы равны ${2*b} и ${b} см.`,'см')
 }
];

workouts.right_triangle_projections=[
 {
  segment:([a,b])=>number(`Высота CH из прямого угла треугольника пересекает гипотенузу AB в H. AH = ${a}, HB = ${b} см. Найди AB.`,a+b,`AB = AH + HB = ${a+b} см.`,'см'),
  projection:([a,b])=>choice(`В прямоугольном треугольнике ABC угол C прямой, CH — высота к AB. Какой отрезок является проекцией катета AC на гипотенузу?`,'AH',['HB','CH','AB'],'Точка A уже на гипотенузе, а проекция C — основание высоты H.'),
  heightSquare:([a,b])=>number(`Высота к гипотенузе делит её на части ${a} и ${b} см. Найди квадрат высоты к гипотенузе.`,a*b,`Квадрат высоты равен произведению проекций катетов: ${a} · ${b} = ${a*b}.`,'см²'),
  legSquare:([a,b])=>number(`Гипотенуза равна ${a+b} см, проекция катета — ${a} см. Найди квадрат этого катета.`,a*(a+b),`Умножаем гипотенузу на проекцию катета: ${a+b} · ${a}.`,'см²')
 },
 {
  height:([a,b])=>number(`Высота к гипотенузе делит её на отрезки ${a*a} и ${b*b} см. Найди высоту.`,a*b,`Извлекаем корень из произведения ${a*a} · ${b*b}.`,'см'),
  reverse:([a,b])=>number(`Высота к гипотенузе равна ${a*b} см. Одна из проекций катетов равна ${a*a} см. Найди другую.`,b*b,`Квадрат высоты — произведение проекций. Делим ${(a*b)**2} на ${a*a}.`,'см'),
  leg:([a,b,c])=>number(`Высота к гипотенузе делит её на части ${a*a} и ${b*b} см. Найди катет с меньшей проекцией.`,a*c,`Гипотенуза равна ${c*c} см. Катет равен √(${c*c} · ${a*a}).`,'см'),
  area:([a,b])=>number(`Высота к гипотенузе делит её на отрезки ${a*a} и ${b*b} см. Найди площадь всего треугольника.`,rational((a*a+b*b)*a*b,2),`Гипотенуза равна ${a*a+b*b} см, высота — ${a*b} см. Делим их произведение пополам.`,'см²')
 },
 {
  areaRatio:([a,b])=>number(`Высота из прямого угла делит гипотенузу на отрезки ${a} и ${b} см. Какую часть площади большого треугольника занимает треугольник над меньшим отрезком?`,rational(a,a+b),'У двух частей одинаковая высота к гипотенузе. Доля площади равна доле меньшего основания.'),
  reconstruct:([a,b,c])=>number(`Высота к гипотенузе равна ${a*b} см, а катет с большей проекцией равен ${b*c} см. Найди гипотенузу.`,c*c,
   `В малом прямоугольном треугольнике с этим катетом в роли гипотенузы находим проекцию √((${b*c})² − (${a*b})²) = ${b*b}. Квадрат исходного катета делим на его проекцию.`,'см'),
  ratio:([a,b])=>number(`Проекции катетов относятся как ${a*a} : ${b*b}. Гипотенуза равна ${2*(a*a+b*b)} см. Найди высоту к гипотенузе.`,2*a*b,
   `На одну долю приходится 2 см. Проекции равны ${2*a*a} и ${2*b*b} см. Высота — квадратный корень из их произведения.`,'см'),
  difference:([a,b,c])=>number(`Катеты равны ${a*c} и ${b*c} см. На сколько сантиметров отличаются их проекции на гипотенузу?`,b*b-a*a,
   `Гипотенуза равна ${c*c} см. Квадраты катетов делим на гипотенузу: проекции ${a*a} и ${b*b} см.`,'см')
 }
];

workouts.similarity_constructions=[
 {
  angles:()=>choice('Что можно построить сначала по двум заданным углам?', 'Любой треугольник с этими углами', ['Сразу единственный треугольник нужного размера','Только прямоугольный треугольник'],'Два угла задают форму. Масштаб выбирается с помощью дополнительной длины.'),
  scale:([a,b])=>number(`Вспомогательный отрезок длиной ${a} см должен перейти в отрезок длиной ${2*a} см. Каков коэффициент подобия?`,2,`Искомую длину делим на вспомогательную: ${2*a} : ${a}.`),
  side:([a,b])=>number(`В черновом треугольнике сторона равна ${a} см. При построении увеличиваем все длины в ${b} раз. Найди соответствующую сторону.`,a*b,`Умножаем ${a} см на коэффициент ${b}.`,'см'),
  use:()=>choice('Что сохраняется при переходе от чернового треугольника к подобному треугольнику другого размера?','Углы',['Длины всех сторон','Периметр','Площадь'],'При подобии углы остаются равными, а линейные размеры меняются в одном отношении.')
 },
 {
  perimeter:([a,b,c])=>number(`Найди меньшую сторону искомого треугольника с отношением сторон ${a} : ${b} : ${c} и периметром ${3*(a+b+c)} см.`,3*a,
   `Вспомогательный периметр ${a+b+c} см. Чтобы получить заданный, все стороны увеличиваем втрое.`,'см'),
  altitude:([a,b,c])=>number(`У вспомогательного прямоугольного треугольника катеты ${a} и ${b} см. Искомый треугольник подобен ему, высота к стороне, соответствующей катету ${a} см, равна ${2*b} см. Найди соответствующий катет.`,2*a,
   `Высота к соответствующей стороне у вспомогательного треугольника равна ${b}. Коэффициент подобия 2.`,'см'),
  bisector:([a,b])=>number(`У построенного по углам треугольника биссектриса равна ${a} см, а прилежащая к этому углу сторона — ${b} см. Найди соответствующую сторону искомого треугольника, если биссектриса должна быть ${3*a} см.`,3*b,
   'Соответственные биссектрисы изменяются в том же отношении, что и стороны. Здесь масштаб равен 3.','см'),
  condition:([a,b])=>choice(`Известны отношение двух сторон искомого треугольника ${a} : ${b} и угол между ними. Что достаточно сделать на первом шаге построения методом подобия?`,
   `Построить заданный угол и отложить от вершины ${a} и ${b} единиц`,['Отложить равные стороны','Построить сразу прямоугольный треугольник'],'Две стороны в верном отношении и угол между ними задают форму по признаку подобия.')
 },
 {
  area:([a,b,c])=>number(`У вспомогательного прямоугольного треугольника катеты ${a} и ${b} см. Какую гипотенузу нужно построить у подобного треугольника площадью ${2*a*b} см²?`,2*c,
   `Площадь увеличилась в 4 раза. Масштаб длин равен 2. Гипотенуза вспомогательного треугольника равна ${c} см.`,'см'),
  feasibility:([a,b,c])=>choice(`У вспомогательного треугольника стороны ${a}, ${b}, ${c} см. Можно ли построить подобный, у которого две меньшие стороны равны ${2*a} и ${3*b} см?`,'Нет',['Да'],'Первая сторона потребовала бы масштаба 2, вторая — 3. Для подобия масштаб должен быть общим.'),
  difference:([a,b,c])=>number(`Искомый треугольник подобен вспомогательному со сторонами ${a}, ${b}, ${c} см. Разность его большей и меньшей сторон равна ${3*(c-a)} см. Найди его периметр.`,3*(a+b+c),
   `Вспомогательная разность ${c-a} см. Значит, коэффициент подобия 3, умножаем вспомогательный периметр на 3.`,'см'),
  ratioArea:([a,b,c])=>number(`Искомый треугольник подобен треугольнику со сторонами ${a}, ${b}, ${c} см. Его периметр на ${2*(a+b+c)} см больше. Найди площадь искомого треугольника.`,rational(9*a*b,2),
   `Искомый периметр в 3 раза больше, значит площадь в 9 раз больше. Площадь вспомогательного прямоугольного треугольника равна половине произведения катетов.`,'см²'),
  constructionPlan:([a,b,c])=>choice(
   `Нужно построить треугольник по двум углам и высоте ${2*a} см к основанию. У вспомогательного треугольника с этими углами основание ${c} см и высота ${a} см. Как завершить построение?`,
   `Отложить основание ${2*c} см и построить на его концах заданные углы внутрь одной полуплоскости`,
   [`Отложить основание ${c+a} см и построить заданные углы`,`Отложить основание ${c} см и отметить вершину на высоте ${2*a} см`,`Отложить основание ${2*a} см и построить заданные углы`],
   `По двум углам треугольники подобны. Высота удваивается, значит основание равно ${2*c} см. Пересечение лучей заданных углов даёт третью вершину.`),
  constructionProof:([a,b])=>choice(
   `Вспомогательный треугольник построили по заданному отношению двух сторон ${a} : ${b} и углу между ними. Затем все стороны увеличили втрое, чтобы получить заданный периметр. Как обосновать, что итоговый треугольник удовлетворяет всем условиям?`,
   'При подобии угол сохраняется, отношение сторон сохраняется, а периметр утраивается',
   ['При подобии увеличивается только периметр, стороны сохраняются','Отношение сторон утраивается вместе с периметром','Достаточно проверить один угол: он определяет и отношение сторон, и периметр'],
   'Каждая сторона умножается на 3, поэтому отношение не меняется, а сумма сторон увеличивается втрое. Соответственные углы подобных треугольников равны.')
 }
];

function circleLineDiagram(task,radius,distance){
 return diagram(task,{kind:'g7-g8-circle-line',radius,distance,
  aria:distance?'Окружность с центром O и прямая, перпендикулярная отрезку OH.':'Прямая проходит через центр O окружности.'});
}
function circlePairDiagram(task,big,small,distance,tangents=false){
 return diagram(task,{kind:'g7-g8-circle-pair',big,small,distance,tangents,
  aria:tangents?'Две окружности и их общие касательные.':'Две окружности с центрами O₁ и O₂.'});
}
function drawCircleLine({radius,distance}){
 const scale=Math.min(126/radius,150/Math.max(1,distance)),x=320,y=220;
 const level=y-distance*scale,end=x+208;
 let svg=g6GeoCircle(x,y,radius*scale)+g6GeoLine(x-208,level,end,level,'geo-line g8-tested-line');
 if(distance){
  svg+=g6GeoLine(x,y,x,level,'geo-guide')+g6GeoPoint(x,level,'H',14,-11)+
   g6RightAngleMarker({x,y:level},{x:1,y:0},{x:0,y:1},18);
 }
 return svg+g6GeoPoint(x,y,'O',13,21);
}
function drawCirclePair({big,small,distance,tangents}){
 const scale=Math.min(420/(big+Math.max(big,distance+small)),122/big);
 const x=(640+(big-Math.max(big,distance+small))*scale)/2,y=200,secondX=x+distance*scale;
 let svg=g6GeoCircle(x,y,big*scale)+g6GeoCircle(secondX,y,small*scale);
 if(tangents&&distance>0){
  for(const side of [1,-1]){
   const horizontal=(big-side*small)/distance;
   if(horizontal>1)continue;
   const vertical=Math.sqrt(1-horizontal*horizontal);
   for(const normalY of vertical===0?[0]:[vertical,-vertical]){
    const ax=x+horizontal*big*scale,ay=y+normalY*big*scale;
    const bx=secondX+side*horizontal*small*scale,by=y+side*normalY*small*scale;
    const dx=normalY,dy=-horizontal;
    const midX=(ax+bx)/2,midY=(ay+by)/2,half=Math.max(58,Math.hypot(ax-bx,ay-by)/2+31);
    svg+=g6GeoLine(midX-dx*half,midY-dy*half,midX+dx*half,midY+dy*half,'geo-line g8-common-tangent');
   }
  }
 }
 if(distance===0)return svg+g6GeoPoint(x,y,'O',12,-13);
 return svg+g6GeoPoint(x,y,'O₁',-26,-13)+g6GeoPoint(secondX,y,'O₂',10,20);
}

function lineRelation(distance,radius){return distance<radius?'Секущая':distance===radius?'Касательная':'Не пересекает окружность';}
const lineRelations=['Секущая','Касательная','Не пересекает окружность'];
function linePositionChoice(question,distance,radius,ex){
 const answer=lineRelation(distance,radius);
 return choice(question,answer,lineRelations.filter(value=>value!==answer),ex);
}

