const circlePositions=['Вне друг друга','Внешнее касание','Две общие точки','Внутреннее касание','Одна внутри другой без касания'];
function circlePosition(big,small,d){
 const sum=big+small,difference=big-small;
 if(d>sum)return 0;
 if(d===sum)return 1;
 if(d>difference)return 2;
 return d===difference?3:4;
}
function pairPositionChoice(question,a,b,d,ex){
 const answer=circlePositions[circlePosition(b,a,d)];
 return choice(question,answer,circlePositions.filter(value=>value!==answer),ex);
}
function tangentCount(big,small,d){return 4-circlePosition(big,small,d);}
function pairGiven(a,b,d){return `Радиусы окружностей ${a} и ${b} см. Расстояние между центрами ${d} см.`;}

