const originalTopicCount=g8AllTopics().length;
for(const [index,[raw,[parent,title]]] of Object.entries(newTopics).entries()){
 const base=g8InfoById('g8:'+parent);
 const group=G8_GROUPS.find(item=>item.topics.includes(base));
 const chapter=chapters.find(chapter=>chapter.items.some(([, ,ids])=>ids.includes(raw)));
 const source=base.course==='algebra'?'Макарычев и др., 2024':base.course==='geometry'?'Атанасян и др., 2023':
  'Высоцкий и Ященко, 2023, часть '+(['VII','VIII','IX'].includes(chapter.chapter)?1:2);
 const section=chapter.title;
 const topic={...base,id:'g8:'+raw,title,shortTitle:title,section,source,textbookRef:source,order:originalTopicCount+index+1,rendererType:'quiz',plannedRendererType:'quiz'};
 group.topics.push(topic);
}
const catalogAudit=g8CatalogAudit;
g8CatalogAudit=function(){
 const report=catalogAudit(),topics=g8AllTopics(),ids=new Set(topics.map(topic=>topic.id)),orders=new Set(topics.map(topic=>topic.order));
 const issues=report.issues.filter(issue=>issue!=='count'&&issue!=='order');
 if(ids.size!==originalTopicCount+Object.keys(newTopics).length)issues.push('count');
 const linked=chapters.flatMap(({items})=>items.flatMap(([, ,rawIds])=>rawIds.map(raw=>'g8:'+raw)));
 if(chapters.some(({items})=>items.some(([, ,rawIds])=>!rawIds.length))||linked.some(id=>!ids.has(id))||new Set(linked).size!==ids.size)issues.push('textbook-links');
 if(orders.size!==topics.length||topics.some(topic=>topic.order<1||topic.order>topics.length))issues.push('order');
 return {...report,issues,ok:issues.length===0};
};

