function tangentChordSketch(task,arc,showArc=true){
 const center={x:300,y:190},r=118;
 return diagram(task,{kind:'g7-qa-angle7779',type:'tangent',cx:center.x,cy:center.y,r,arc,
  A:g8CirclePoint815(center,r,0),B:g8CirclePoint815(center,r,arc),C:g8CirclePoint815(center,r,210),
  labels:showArc?{arc:arc+'°'}:{arc:'?'},withInscribed:false,aria:'Касательная в точке A и хорда AB.'});
}
function intersectingChordsSketch(task,near,far,showAngle=false){
 const center={x:315,y:200},r=132;
 const A=g8CirclePoint815(center,r,0),B=g8CirclePoint815(center,r,180);
 const C=g8CirclePoint815(center,r,near),D=g8CirclePoint815(center,r,180+far);
 const t=(center.y-C.y)/(D.y-C.y),P={x:C.x+t*(D.x-C.x),y:center.y};
 const labels=showAngle?{angle:(near+far)/2+'°'}:{arcAC:near+'°',arcBD:far+'°'};
 return diagram(task,{kind:'g7-g8-exact8082',type:'inside',cx:center.x,cy:center.y,r,A,B,C,D,P,labels,
  aria:'Хорды AB и CD пересекаются в точке P внутри окружности.'});
}
