function cyclicSketch(task,angle,marks){
 const center={x:315,y:200},r=134,positions={A:0,B:20,C:20+angle,D:20+2*angle};
 const vertices=Object.fromEntries(Object.entries(positions).map(([k,value])=>[k,g8CirclePoint815(center,r,value)]));
 return diagram(task,{kind:'g7-g8-exact8082',type:'cyclic',cx:center.x,cy:center.y,r,vertices,labels:marks,
  aria:'Четырёхугольник ABCD вписан в окружность.'});
}
function tangentialSketch(task,u,v,labels){
 const a=2*u*u,b=2*v*v,h=2*u*v,k=Math.min(245/b,215/h);
 const point=(x,y)=>({x:320+k*x,y:316-k*y});
 const vertices={A:point(-b/2,0),B:point(b/2,0),C:point(a/2,h),D:point(-a/2,h)};
 const O=point(0,h/2),T=point(0,0),R=g7FootToLine(O,vertices.B,vertices.C);
 return diagram(task,{kind:'g7-g8-exact8082',type:'tangential',cx:O.x,cy:O.y,r:k*h/2,vertices,O,T,R,labels,
  aria:'Окружность касается всех сторон равнобедренной трапеции ABCD.'});
}

